import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadKalam = makeLoadFont('Kalam');

// Load fonts at module level to prevent flickering
const { fontFamily: interFamily } = loadInter();
const { fontFamily: kalamFamily } = loadKalam();



export type PillCounterProps = Record<string, any>;

const PillCounter: React.FC<PillCounterProps> = ({
  backgroundColor = "#de662b",
  transparentBackground = false,
  durationInSeconds = 5,
  pillBackgroundColor = "#f3efe5",
  accentColor = "#2a2829",
  labelText = "views",
  startNumber = 3044615385,
  endNumber = 3454666344,
  suffix = "+",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background logic safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing reference
  const s = Math.min(width, height);

  // Animate the container popping in
  const containerScale = spring({
    frame,
    fps,
    config: {
      damping: 14,
      stiffness: 150,
      mass: 0.8,
    },
  });

  // Calculate the counter progress
  // Start counting slightly after the scale animation finishes (e.g., at 0.5s)
  // Finish counting slightly before the end of the video (e.g., 1s before)
  const startCountFrame = fps * 0.5;
  const endCountFrame = (durationInSeconds - 0.5) * fps;

  const counterProgress = interpolate(
    frame,
    [startCountFrame, endCountFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  // Derive the current number based on progress
  const currentNumber = Math.floor(
    startNumber + (endNumber - startNumber) * counterProgress
  );

  // Format with commas
  const formattedNumber = new Intl.NumberFormat("en-US").format(currentNumber);
  const displayString = `${formattedNumber}${suffix}`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: pillBackgroundColor,
          padding: `${s * 0.06}px ${s * 0.15}px`,
          borderRadius: "999px",
          border: `${s * 0.005}px solid ${accentColor}`,
          // Create the hard drop-shadow effect seen in the reference
          boxShadow: `0px ${s * 0.015}px 0px 0px ${accentColor}`,
          transform: `scale(${containerScale})`,
          // Ensure smooth animation without CSS transition interference
          transition: "none",
        }}
      >
        {/* Label (views) */}
        <div
          style={{
            fontFamily: kalamFamily,
            fontSize: s * 0.09,
            color: accentColor,
            lineHeight: 1,
            marginBottom: s * 0.01,
            // Slight adjustment to match the handwritten visual weight
            fontWeight: 600,
          }}
        >
          {labelText}
        </div>

        {/* Counter Number */}
        <div
          style={{
            fontFamily: interFamily,
            fontSize: s * 0.16,
            fontWeight: 900, // Black weight
            color: accentColor,
            lineHeight: 1,
            letterSpacing: "-0.04em", // Tighter letter spacing for large numbers
            whiteSpace: "nowrap",
          }}
        >
          {displayString}
        </div>
      </div>
    </AbsoluteFill>
  );
};

